using System;
using System.IO;
using System.Linq;
using Mmorpg.Domain;
using Mmorpg.Runtime;
using NUnit.Framework;

namespace Mmorpg.Tests
{
    public sealed class WorldEventTests
    {
        private JourneyEngine journey;
        private WorldEventOrchestrator world;
        private SimulatedWorldClock clock;
        private int sequence;
        [SetUp] public void Setup() { journey=new JourneyEngine(); clock=new SimulatedWorldClock(); sequence=0; world=new WorldEventOrchestrator(ForestContent.Actor,ForestContent.World,clock); }
        private GameEvent Input(EventType type,string source) => new GameEvent{eventId="wtest-"+(++sequence),actorId=ForestContent.Actor,worldId=ForestContent.World,sourceId=source,eventType=type,timestamp=sequence};
        private void Trace() { var e=Input(EventType.TraceExamined,ForestContent.Trace); e.trace=new TracePayload{traceId=ForestContent.Trace}; Assert.That(journey.ApplyValidated(e),Is.True); }
        private void Defeat() { var e=Input(EventType.CreatureDefeated,"combat"); e.creature=new CreaturePayload{creatureId=ForestContent.Wolf,encounterId="wolf-1"}; Assert.That(journey.ApplyValidated(e),Is.True); }
        private void Investigate() { Defeat(); foreach(var type in new[]{EventType.EvidenceCollected,EventType.EvidenceDelivered}) { var e=Input(type,type==EventType.EvidenceCollected?"sample-drop":ForestContent.Mira); e.evidence=new EvidencePayload{evidenceId=ForestContent.Sample,encounterId="wolf-1",recipientId=type==EventType.EvidenceDelivered?ForestContent.Mira:null}; Assert.That(journey.ApplyValidated(e),Is.True); } }
        private void CombatAction(string action) { var e=Input(EventType.CombatActionVerified,"combat"); e.combat=new CombatPayload{actionId=action,targetId=action==CombatActions.PreparedDodge?ForestContent.Wolf:"training-dummy",encounterId="combat-1",preparedAttackId=action==CombatActions.PreparedDodge?"prepared-1":null}; Assert.That(journey.ApplyValidated(e),Is.True); }
        private void Sync(bool resolve=true) { world.Synchronize(journey); if(resolve) world.ResolveDeterministic(journey); }
        private JourneySnapshot Save() { world.Tick(journey); var s=journey.Snapshot(); s.version=3; s.world=world.Snapshot(); return s; }
        [Test] public void NoCandidatesAndRejectionEvidenceHaveStableRuleIds() { Assert.That(world.PendingEvaluation(),Is.Null); Assert.That(world.ResolveDeterministic(journey),Is.False); Assert.That(world.ExplainEligibility().Single(x=>x.candidateId==WorldEventContent.Alert).rejectedRules,Does.Contain("fact:investigation-confirmed")); }
        [Test] public void TrackingAndCombatAndRegionAreRequired() { Trace(); Sync(false); Assert.That(world.PendingEvaluation(),Is.Null); Defeat(); Sync(false); Assert.That(world.PendingEvaluation().eligibleConsequences,Is.EquivalentTo(new[]{WorldEventContent.Tracks,"none"})); }
        [Test] public void AndOrTimeAndPreviousEventConditionsAreConventionalRules() {
            var c=new WorldCondition{kind=WorldConditionKind.Or,ruleId="either",children={new WorldCondition{kind=WorldConditionKind.Fact,ruleId="no",value="absent"},new WorldCondition{kind=WorldConditionKind.GameTimeAtLeast,ruleId="time",time=10}}};
            var s=world.Snapshot(); s.gameTime=10; var e=new EligibilityEvidence(); Assert.That(WorldEligibility.Evaluate(c,s,e),Is.True); Assert.That(e.rejectedRules,Does.Contain("no"));
        }
        [Test] public void SelectingOneDoesNotDiscardIndependentCandidates() { Trace(); Investigate(); CombatAction(CombatActions.PreparedDodge); Sync(false); world.Interact(ForestContent.Orin,journey); Assert.That(world.PendingEvaluation().candidates.Count,Is.EqualTo(3)); world.ResolveDeterministic(journey); Assert.That(world.Snapshot().opportunities.Count,Is.EqualTo(2)); Assert.That(world.Snapshot().scheduled.Count,Is.EqualTo(1)); Assert.That(world.Snapshot().decisions.Count,Is.EqualTo(3)); }
        [Test] public void InvalidSelectionAndProbabilitiesCannotApply() { Investigate(); Sync(false); var d=WorldEventContent.Deterministic(world.PendingEvaluation()); d.selectedConsequence="grant-ability"; Assert.That(world.TryApplyDecision(d,journey),Is.False); d=WorldEventContent.Deterministic(world.PendingEvaluation()); d.confidence=double.NaN; Assert.That(world.TryApplyDecision(d,journey),Is.False); Assert.That(world.Snapshot().scheduled,Is.Empty); }
        [Test] public void JevSelectsOnlyAllowedCandidatesWithSeparateMetrics() { Investigate(); Sync(false); var d=WorldEventContent.Deterministic(world.PendingEvaluation()); d.provider="TypeSafe"; d.model="typesafe/jev-1.13-20260917"; d.decisionId="gen-dec-mock"; d.confidence=0.4; d.probabilities=new System.Collections.Generic.Dictionary<string,double>{{WorldEventContent.Alert,0.8},{"none",0.2}}; Assert.That(world.TryApplyDecision(d,journey),Is.True); Assert.That(world.Snapshot().decisions.Single().confidence,Is.EqualTo(0.4)); }
        [Test] public void NoneDefersOptionalCandidatesButCannotBlockExistingTechnique() { Investigate(); Sync(false); var d=WorldEventContent.Deterministic(world.PendingEvaluation()); d.selectedConsequence="none"; Assert.That(world.TryApplyDecision(d,journey),Is.True); Assert.That(world.PendingEvaluation(),Is.Null); Assert.That(journey.HasAbility(ForestContent.Technique),Is.True); Trace(); Sync(false); Assert.That(world.PendingEvaluation().eligibleConsequences,Does.Contain(WorldEventContent.Alert)); }
        [Test] public void StaleDecisionIsRejectedAfterRelevantWorldChange() { Investigate(); Sync(false); var d=WorldEventContent.Deterministic(world.PendingEvaluation()); var cause=world.Snapshot().facts.First().id; Assert.That(world.SetRegionalThreat(false,cause,journey),Is.True); Assert.That(world.TryApplyDecision(d,journey),Is.False); Assert.That(world.Snapshot().scheduled,Is.Empty); }
        [Test] public void PrivateDodgeDoesNotGiveOrinKnowledgeUntilConversation() { CombatAction(CombatActions.PreparedDodge); Sync(); Assert.That(world.Snapshot().knowledge,Is.Empty); Assert.That(world.Status(WorldEventContent.Training),Is.Null); world.Interact(ForestContent.Orin,journey); world.ResolveDeterministic(journey); Assert.That(world.Status(WorldEventContent.Training),Is.EqualTo(WorldOpportunityStatus.Discovered)); Assert.That(world.Snapshot().knowledge.Single().source,Is.EqualTo(KnowledgeSource.Conversation)); }
        [Test] public void SourcedNoticeWaitsForGameClockAndPropagatesPublicKnowledge() { Investigate(); Sync(); Assert.That(world.NoticePublished,Is.False); clock.RealMilliseconds=1000000; world.Tick(journey); Assert.That(world.NoticePublished,Is.False); clock.GameMilliseconds=14999; world.Tick(journey); Assert.That(world.NoticePublished,Is.False); clock.GameMilliseconds=15000; world.Tick(journey); Assert.That(world.NoticePublished,Is.True); Assert.That(world.Snapshot().knowledge.Any(k=>k.npcId==ForestContent.Orin&&k.source==KnowledgeSource.PublicNotice),Is.True); Assert.That(world.Journal(),Does.Not.Contain("Quadro:")); world.Interact("notice-board",journey); Assert.That(world.Journal(),Does.Contain("Quadro:")); }
        [Test] public void RealTimeOfflineCatchupIsExplicitBoundedAndIdempotent() { world=new WorldEventOrchestrator(ForestContent.Actor,ForestContent.World,clock,new WorldEventSettings{alertTimeBasis=WorldTimeBasis.Real,maximumDuePerTick=1}); Investigate(); Sync(); var s=Save(); journey=JourneyEngine.Restore(s); clock.RealMilliseconds=999999999; world=WorldEventOrchestrator.Restore(s.world,journey,clock); Assert.That(world.Tick(journey),Is.True); Assert.That(world.Tick(journey),Is.False); Assert.That(world.Snapshot().scheduled.Count(x=>x.executed),Is.EqualTo(1)); }
        [Test] public void AgendaCanWaitForFutureFactAndNpcInteractionWithoutRealWaits() { world=new WorldEventOrchestrator(ForestContent.Actor,ForestContent.World,clock,new WorldEventSettings{alertAfterFactKind=WorldEventContent.Tracking,alertAfterNpcId=ForestContent.Orin}); Investigate(); Sync(); clock.Advance(20000); world.Tick(journey); Assert.That(world.NoticePublished,Is.False); Trace(); Sync(); world.Tick(journey); Assert.That(world.NoticePublished,Is.False); world.Interact(ForestContent.Orin,journey); world.Tick(journey); Assert.That(world.NoticePublished,Is.True); }
        [Test] public void InvalidatedConditionsCancelDueConsequences() { Investigate(); Sync(); world.SetRegionalThreat(false,world.Snapshot().facts.First().id,journey); clock.Advance(20000); world.Tick(journey); Assert.That(world.NoticePublished,Is.False); Assert.That(world.Snapshot().scheduled.Single().cancelled,Is.True); }
        [Test] public void SaveLoadPendingEventsAndRestartReplayDoNotDuplicate() { Investigate(); Sync(); clock.Advance(10000); var saved=Save(); var store=new MemoryJourneyPersistence(); store.Save(saved); journey=JourneyEngine.Restore(store.Load()); world=WorldEventOrchestrator.Restore(store.Load().world,journey,clock); Assert.That(world.Synchronize(journey),Is.False); clock.Advance(5000); world.Tick(journey); store.Save(Save()); journey=JourneyEngine.Restore(store.Load()); world=WorldEventOrchestrator.Restore(store.Load().world,journey,clock); Assert.That(world.Tick(journey),Is.False); Assert.That(world.Snapshot().decisions.Count,Is.EqualTo(1)); Assert.That(world.Snapshot().knowledge.Count,Is.EqualTo(2)); }
        [Test] public void CorruptProjectionAndUnverifiedSourceAreRejected() { Investigate(); Sync(); var s=Save(); s.world.noticePublished=true; Assert.Throws<ArgumentException>(()=>JourneyEngine.Restore(s)); s=Save(); s.world.history.First().causeId="invented"; Assert.Throws<ArgumentException>(()=>JourneyEngine.Restore(s)); }
        [Test] public void ClueMustBeExaminedBeforeOrinCanConcludeInvestigation() { Trace(); Defeat(); Sync(); Assert.That(world.ClueVisible,Is.True); Assert.That(world.Journal(),Does.Not.Contain(WorldEventContent.Title(WorldEventContent.Tracks))); world.Interact(ForestContent.Orin,journey); Assert.That(world.Status(WorldEventContent.Tracks),Is.EqualTo(WorldOpportunityStatus.Hidden)); world.Interact(WorldEventContent.Tracks,journey); world.Interact(ForestContent.Orin,journey); Assert.That(world.Status(WorldEventContent.Tracks),Is.EqualTo(WorldOpportunityStatus.Completed)); Assert.That(world.ClueVisible,Is.False); }
        [Test] public void TrainingRequiresOptInAndNewVerifiedHitWithoutAbilityReward() { CombatAction(CombatActions.PreparedDodge); Sync(); world.Interact(ForestContent.Orin,journey); world.ResolveDeterministic(journey); Assert.That(world.Status(WorldEventContent.Training),Is.EqualTo(WorldOpportunityStatus.Discovered)); world.Interact(ForestContent.Orin,journey); Assert.That(world.Status(WorldEventContent.Training),Is.EqualTo(WorldOpportunityStatus.Started)); CombatAction(CombatActions.TrainingHit); Sync(); Assert.That(world.Status(WorldEventContent.Training),Is.EqualTo(WorldOpportunityStatus.Completed)); Assert.That(journey.Snapshot().abilities,Is.Empty); }
        [Test] public void IgnoredOpportunitiesExpireAndUndiscoveredInformationStaysPrivate() { Trace(); Defeat(); Sync(); clock.Advance(900000); world.Tick(journey); Assert.That(world.Status(WorldEventContent.Tracks),Is.EqualTo(WorldOpportunityStatus.Expired)); Assert.That(world.ClueVisible,Is.False); Assert.That(world.Journal(),Is.Empty); Assert.That(world.Interact(WorldEventContent.Tracks,journey),Is.False); }
        [Test] public void ActiveLimitRetainsCandidatesUntilSlotExpires() { world=new WorldEventOrchestrator(ForestContent.Actor,ForestContent.World,clock,new WorldEventSettings{maximumActiveOpportunities=1}); Trace(); Defeat(); CombatAction(CombatActions.PreparedDodge); Sync(); world.Interact(ForestContent.Orin,journey); Assert.That(world.PendingEvaluation(),Is.Null); clock.Advance(900000); world.Tick(journey); Assert.That(world.PendingEvaluation().eligibleConsequences,Does.Contain(WorldEventContent.Training)); world.ResolveDeterministic(journey); Assert.That(world.Snapshot().opportunities.Count(o=>o.status==WorldOpportunityStatus.Discovered),Is.EqualTo(1)); }
        [Test] public void LegacyV2SaveMigratesWithoutChangingJourneyOrTechnique() { Investigate(); journey.TryApplyDecision(MiraReactions.Deterministic(journey.PendingMiraDecision())); var legacy=journey.Snapshot(); Assert.That(legacy.version,Is.EqualTo(2)); var restored=JourneyEngine.Restore(legacy); Assert.That(restored.Snapshot().world,Is.Null); Sync(); var s=Save(); Assert.That(JourneyEngine.Restore(s).HasAbility(ForestContent.Technique),Is.True); Assert.That(s.inputs.Count,Is.EqualTo(legacy.inputs.Count)); Assert.That(s.decisions.Single().decisionId,Is.EqualTo(legacy.decisions.Single().decisionId)); }
        [Test] public void FileSaveRecoveryIncludesWorldAndDoesNotTouchPlayerSave() { var dir=Path.Combine(Path.GetTempPath(),"m04-tests-"+Guid.NewGuid().ToString("N")); try { var store=new JsonJourneyPersistence(Path.Combine(dir,"journey.json")); Investigate(); Sync(); store.Save(Save()); clock.Advance(20000); world.Tick(journey); store.Save(Save()); File.WriteAllText(Path.Combine(dir,"journey.json"),"broken"); Assert.That(store.Load().world.noticePublished,Is.False); Assert.That(store.RecoveryMessage,Is.Not.Null); } finally { if(Directory.Exists(dir)) Directory.Delete(dir,true); } }
        [Test] public void ThreeIndependentHistoriesProduceDifferentPersistentConsequences() {
            Investigate(); Sync(); clock.Advance(15000); world.Tick(journey); var a=Save();
            Setup(); Trace(); Defeat(); Sync(); var b=Save();
            Setup(); CombatAction(CombatActions.PreparedDodge); Sync(); world.Interact(ForestContent.Orin,journey); world.ResolveDeterministic(journey); var c=Save();
            Assert.That(a.world.noticePublished,Is.True); Assert.That(a.world.opportunities,Is.Empty);
            Assert.That(b.world.opportunities.Single().id,Is.EqualTo(WorldEventContent.Tracks)); Assert.That(b.world.scheduled,Is.Empty);
            Assert.That(c.world.opportunities.Single().id,Is.EqualTo(WorldEventContent.Training)); Assert.That(c.abilities,Is.Empty);
            foreach(var saved in new[]{a,b,c}) { var restored=JourneyEngine.Restore(saved); var repeated=WorldEventOrchestrator.Restore(saved.world,restored,new SimulatedWorldClock()); Assert.That(repeated.Synchronize(restored),Is.False); Assert.That(repeated.ResolveDeterministic(restored),Is.False); Assert.That(repeated.Snapshot().history.Count,Is.EqualTo(saved.world.history.Count)); }
        }
        [Test] public void BothLegacyRoutesStillCompleteAndWeaknessRemainsUnique() { Trace(); var e=Input(EventType.NpcInteracted,ForestContent.Orin); e.npc=new NpcPayload{npcId=ForestContent.Orin,sharedFact=ForestContent.Trace}; journey.ApplyValidated(e); Investigate(); Sync(); Assert.That(journey.Status(ForestContent.RouteA),Is.EqualTo(OpportunityStatus.Completed)); Assert.That(journey.Status(ForestContent.RouteB),Is.EqualTo(OpportunityStatus.Completed)); Assert.That(journey.Snapshot().abilities,Is.EquivalentTo(new[]{ForestContent.Technique})); Assert.That(JourneyEngine.Restore(Save()).Snapshot().abilities.Count,Is.EqualTo(1)); }
        [Test] public void NewJourneysWithSameRevisionUseDifferentEvaluationIdsAndReloadKeepsIdentity() {
            Trace(); Defeat(); Sync(false); string first=world.PendingEvaluation().eventId;
            var saved=Save(); var restored=JourneyEngine.Restore(saved); var replay=WorldEventOrchestrator.Restore(saved.world,restored,clock);
            Assert.That(replay.PendingEvaluation().eventId,Is.EqualTo(first));
            Setup(); sequence=100; Trace(); Defeat(); Sync(false);
            Assert.That(world.Revision,Is.EqualTo(saved.world.revision)); Assert.That(world.PendingEvaluation().eventId,Is.Not.EqualTo(first));
        }
        [Test] public void EligibilityAuditPersistsPassedAndRejectedRulesAndCannotBeTampered() {
            Trace(); Defeat(); Sync(false); var saved=Save();
            Assert.That(saved.world.eligibilityHistory.Last().evidence.Single(e=>e.candidateId==WorldEventContent.Tracks).eligible,Is.True);
            Assert.That(JourneyEngine.Restore(saved).Snapshot().world.eligibilityHistory.Count,Is.EqualTo(saved.world.history.Count));
            saved.world.eligibilityHistory.Last().evidence.Single(e=>e.candidateId==WorldEventContent.Tracks).eligible=false;
            Assert.Throws<ArgumentException>(()=>JourneyEngine.Restore(saved));
        }
        [Test] public void PacifiedRegionClosesInteractiveClueAndCannotConcludeInvalidInvestigation() {
            Trace(); Defeat(); Sync(); world.Interact(WorldEventContent.Tracks,journey);
            world.SetRegionalThreat(false,world.Snapshot().facts.First().id,journey);
            Assert.That(world.Status(WorldEventContent.Tracks),Is.EqualTo(WorldOpportunityStatus.Closed)); Assert.That(world.ClueVisible,Is.False);
            world.Interact(ForestContent.Orin,journey); Assert.That(world.Status(WorldEventContent.Tracks),Is.EqualTo(WorldOpportunityStatus.Closed));
        }
    }
}
